CREATE TABLE public.site_content (id text PRIMARY KEY, value text NOT NULL DEFAULT '', updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.site_content TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.site_content TO authenticated;
GRANT ALL ON public.site_content TO service_role;
ALTER TABLE public.site_content ENABLE ROW LEVEL SECURITY;
CREATE POLICY content_read ON public.site_content FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY content_admin ON public.site_content FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE TABLE public.museum_pages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'), title text NOT NULL CHECK (char_length(title) BETWEEN 1 AND 200), description text, banner_url text, caption text, biography text, published boolean NOT NULL DEFAULT false, position integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.museum_pages TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.museum_pages TO authenticated;
GRANT ALL ON public.museum_pages TO service_role;
ALTER TABLE public.museum_pages ENABLE ROW LEVEL SECURITY;
CREATE POLICY pages_read ON public.museum_pages FOR SELECT TO anon, authenticated USING (published);
CREATE POLICY pages_admin ON public.museum_pages FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
ALTER TABLE public.galleries ADD COLUMN page_id uuid REFERENCES public.museum_pages(id) ON DELETE SET NULL;
ALTER TABLE public.galleries ADD COLUMN parent_id uuid REFERENCES public.galleries(id) ON DELETE SET NULL;
ALTER TABLE public.rooms ADD COLUMN page_id uuid REFERENCES public.museum_pages(id) ON DELETE SET NULL;
ALTER TABLE public.artists ADD COLUMN page_id uuid REFERENCES public.museum_pages(id) ON DELETE SET NULL;
CREATE TABLE public.contact_submissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK (char_length(trim(name)) BETWEEN 2 AND 80), email text NOT NULL CHECK (char_length(email) <= 160 AND email ~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$'), phone text CHECK (char_length(phone) <= 30), subject text CHECK (char_length(subject) <= 120), message text NOT NULL CHECK (char_length(trim(message)) BETWEEN 10 AND 4000), created_at timestamptz NOT NULL DEFAULT now());
GRANT INSERT ON public.contact_submissions TO anon;
GRANT SELECT, INSERT, DELETE ON public.contact_submissions TO authenticated;
GRANT ALL ON public.contact_submissions TO service_role;
ALTER TABLE public.contact_submissions ENABLE ROW LEVEL SECURITY;
CREATE POLICY contact_insert ON public.contact_submissions FOR INSERT TO anon, authenticated WITH CHECK (true);
CREATE POLICY contact_admin_read ON public.contact_submissions FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin'));
CREATE POLICY contact_admin_delete ON public.contact_submissions FOR DELETE TO authenticated USING (public.has_role(auth.uid(),'admin'));
CREATE POLICY published_cms_media ON storage.objects FOR SELECT TO anon USING (bucket_id='museo' AND name NOT LIKE 'avatars/%' AND (EXISTS (SELECT 1 FROM public.site_content WHERE value='museo/' || name) OR EXISTS (SELECT 1 FROM public.museum_pages WHERE published AND banner_url='museo/' || name)));
